class Solution:
    def maxNested(self, boxes: List[List[int]]) -> int:
        a = sorted(boxes)
        chain = [1] * len(a)
        for i in range(len(a)):
            for j in range(i):
                if a[j][0] < a[i][0] and a[j][1] < a[i][1]:
                    chain[i] = max(chain[i], chain[j] + 1)
        return max(chain)

