class Solution {
    public int maxNested(int[][] boxes) {
        int[][] a = boxes.clone();
        Arrays.sort(a, (x, y) -> x[0] != y[0] ? x[0] - y[0] : x[1] - y[1]);
        int n = a.length, best = 0;
        int[] chain = new int[n];
        for (int i = 0; i < n; i++) {
            chain[i] = 1;
            for (int j = 0; j < i; j++)
                if (a[j][0] < a[i][0] && a[j][1] < a[i][1]) chain[i] = Math.max(chain[i], chain[j] + 1);
            best = Math.max(best, chain[i]);
        }
        return best;
    }
}

