import bisect

class Solution:
    def maxNested(self, boxes: List[List[int]]) -> int:
        tails = []
        for w, h in sorted(boxes, key=lambda b: (b[0], -b[1])):
            i = bisect.bisect_left(tails, h)
            if i == len(tails):
                tails.append(h)
            else:
                tails[i] = h
        return len(tails)

