class Solution {
    public int maxNested(int[][] boxes) {
        int[][] a = boxes.clone();
        Arrays.sort(a, (x, y) -> x[0] != y[0] ? x[0] - y[0] : y[1] - x[1]);
        int[] tails = new int[a.length];
        int len = 0;
        for (int[] b : a) {
            int lo = 0, hi = len;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (tails[mid] < b[1]) lo = mid + 1; else hi = mid; }
            tails[lo] = b[1];
            if (lo == len) len++;
        }
        return len;
    }
}

