public:
    int maxNested(vector<vector<int>>& boxes) {
        vector<vector<int>> a = boxes;
        sort(a.begin(), a.end(), [](auto& x, auto& y) { return x[0] != y[0] ? x[0] < y[0] : x[1] > y[1]; });
        vector<int> tails;
        for (auto& b : a) {
            auto it = lower_bound(tails.begin(), tails.end(), b[1]);
            if (it == tails.end()) tails.push_back(b[1]);
            else *it = b[1];
        }
        return tails.size();
    }
};

