static int by_rule(const void* x, const void* y) {
    const int *a = *(int* const*) x, *b = *(int* const*) y;
    return a[0] != b[0] ? a[0] - b[0] : b[1] - a[1];
}

int maxNested(int** boxes, int boxesSize, int* boxesColSize) {
    int** a = malloc(boxesSize * sizeof(int*));
    memcpy(a, boxes, boxesSize * sizeof(int*));
    qsort(a, boxesSize, sizeof(int*), by_rule);
    int* tails = malloc(boxesSize * sizeof(int));
    int len = 0;
    for (int i = 0; i < boxesSize; i++) {
        int h = a[i][1], lo = 0, hi = len;
        while (lo < hi) { int mid = (lo + hi) / 2; if (tails[mid] < h) lo = mid + 1; else hi = mid; }
        tails[lo] = h;
        if (lo == len) len++;
    }
    free(a); free(tails);
    return len;
}
